  }

  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      mergeRank,
      classifyHttp,
      classifyBatch,
      normalizeUrl,
      sanitizeText,
      regulatoryHostAllowed,
      tierOf,
      toIso,
      PROVIDER_ORDER,
      OFFICIAL_BY_MODE,
      RESULT_CAP,
      TITLE_MAX,
      URL_MAX,
      SNIPPET_MAX,
      MAX_TEXT_CHARS,
    };
  }
  return module.exports;
})();

const SINGLES = [{"id":"google","gate":"Gate Google","stamp":"Stamp Google"},{"id":"brave","gate":"Gate Brave","stamp":"Stamp Brave"},{"id":"tavily","gate":"Gate Tavily","stamp":"Stamp Tavily"},{"id":"github","gate":"Gate GitHub","stamp":"Stamp GitHub"},{"id":"osv","gate":"Gate OSV","stamp":"Stamp OSV"}];
const planItem = $("Plan").first().json;
const plan = planItem.plan;
const ctx = planItem.ctx;
const now = Date.now();
const read = (name) => {
  try {
    return $(name).first().json;
  } catch (e) {
    return undefined;
  }
};
const entries = [];
for (const s of SINGLES) {
  const gate = read(s.gate);
  if (!gate) continue;
  const out = gate.run ? read(s.stamp) : undefined;
  entries.push(
    MergeRank.classifyHttp({
      id: s.id,
      gate,
      startedAt: gate.startedAt,
      now: out && typeof out.endedAt === "number" ? out.endedAt : now,
      out,
      timeoutMs: plan.timeoutMs,
    }),
  );
}
const kg = read("Gate Keyless");
if (kg) {
  let outs = [];
  if (kg.run) {
    try {
      outs = $("Stamp Keyless").all().map((i) => i.json);
    } catch (e) {
      outs = [];
    }
  }
  const last = outs.reduce((m, o) => (o && typeof o.endedAt === "number" ? Math.max(m, o.endedAt) : m), 0);
  entries.push(
    ...MergeRank.classifyBatch({
      planned: kg.items,
      gate: kg,
      outs,
      startedAt: kg.startedAt,
      now: last || now,
      timeoutMs: plan.timeoutMs,
    }),
  );
}
const ranked = MergeRank.mergeRank({
  entries,
  mode: plan.mode,
  lang: plan.lang,
  maxResults: plan.maxResults,
  now,
});
return [{ json: { ctx, providers: ranked.providers, results: ranked.results } }];

